// The sub-workflow trigger always wraps the input as an array of items.
// The actual query object is contained in the 'query' key of the first item.

const items = $input.all();

if (items.length > 0 && items[0].json && items[0].json.query) {
    // Extract the nested query object
    const finalQuery = items[0].json.query;

    // Create a new item whose JSON is the clean query object
    // This makes the query parameters (queryType, limit, etc.) accessible
    // directly as $json.queryType by the next node (Switch)
    return [{ json: finalQuery }];
}

// Return an empty item if no query was found to prevent errors
return [{}];

/**
 * Unified Redis Query Router v2.1.0 - TIMESTAMP FIX
 * - Fixed seconds/milliseconds mismatch in time filtering
 * - Added comprehensive debugging for empty results
 */

const Redis = require('ioredis');

if (!global.redisPool || global.redisPool.status !== 'ready') {
    console.log('Creating new Redis connection...');
    global.redisPool = new Redis({
        host: 'redis',
        port: 6379,
        db: 0,
        maxRetriesPerRequest: 3,
        enableReadyCheck: true,
        lazyConnect: false,
        keepAlive: 30000,
        retryStrategy(times) {
            return Math.min(times * 50, 2000);
        }
    });

    global.redisPool.on('error', (err) => {
        console.error('Redis pool error:', err.message);
    });
}

const redis = global.redisPool;
const items = $input.all();
const inputData = items[0].json;
const queryType = inputData.queryType;
const limit = inputData.limit || 20;

// Simple cache
if (!global.queryCache) {
    global.queryCache = new Map();
    global.cacheStats = { hits: 0, misses: 0 };
}

function getCacheKey(queryType, params) {
    const relevantParams = { ...params };
    delete relevantParams.limit;
    return `${queryType}:${JSON.stringify(relevantParams)}`;
}

const cacheableQueries = [
    'get_item_stats', 'get_item_traits', 'get_blueprint_materials', 'get_system_details',
    'get_agent_type', 'get_attribute_category', 'get_character_attribute', 'get_industry_activity',
    'get_item_category', 'get_item_classification', 'get_item_flag_info', 'get_item_group',
    'get_item_market_group', 'get_item_meta_level', 'get_jump_connections', 'get_market_group_info',
    'get_system_agents', 'get_system_celestials', 'get_system_security', 'get_system_stations',
    'get_pi_chain', 'get_fitting_attribute', 'get_skill_requirements', 'get_stacking_penalized_attrs',
    'get_fitting_formula', 'get_all_fitting_formulas'
];
const shouldCache = cacheableQueries.includes(queryType);
const cacheKey = shouldCache ? getCacheKey(queryType, inputData) : null;

if (shouldCache && global.queryCache.has(cacheKey)) {
    global.cacheStats.hits++;
    console.log(`[CACHE HIT] ${queryType} (${global.cacheStats.hits} hits, ${global.cacheStats.misses} misses)`);

    return [{
        json: {
            status: 'success',
            query: inputData,
            data: global.queryCache.get(cacheKey),
            cached: true
        }
    }];
}

if (shouldCache) {
    global.cacheStats.misses++;
}

// =====================================================
// HELPER FUNCTIONS
// =====================================================

async function resolveNameToId(name) {
    const nameLower = name.toLowerCase();

    let entityId = await redis.hget('eve:solar_system_name_to_id', nameLower);
    if (entityId) return entityId;

    entityId = await redis.hget('eve:name_to_id', nameLower);
    if (!entityId) {
        throw new Error(`Name not found: ${name}`);
    }
    return entityId;
}

/**
 * FIXED v2.1.0: Timestamps now use SECONDS to match ZSET scores
 */
async function getKillsFromIndex(indexKey, limit, queryParams) {
    const { startDate, endDate, lastHours, lastDays } = queryParams;
    let killIds = [];

    let minScore = '-inf';
    let maxScore = '+inf';

    if (startDate || endDate || lastHours || lastDays) {
        // --- Time-based query (ALL IN SECONDS) ---
        const nowSeconds = Math.floor(Date.now() / 1000);

        if (lastHours) {
            minScore = nowSeconds - (lastHours * 60 * 60);
            maxScore = nowSeconds;
        } else if (lastDays) {
            minScore = nowSeconds - (lastDays * 24 * 60 * 60);
            maxScore = nowSeconds;
        } else {
            // CRITICAL FIX: Convert milliseconds to seconds
            minScore = startDate ? Math.floor(new Date(startDate).getTime() / 1000) : '-inf';
            maxScore = endDate ? Math.floor(new Date(endDate).getTime() / 1000) : '+inf';
        }

        // Debug logging
        const indexTotal = await redis.zcard(indexKey);
        const rangeCount = await redis.zcount(indexKey, minScore, maxScore);

        console.log(`[getKillsFromIndex] Index: ${indexKey}`);
        console.log(`[getKillsFromIndex] Total in index: ${indexTotal}`);
        console.log(`[getKillsFromIndex] Score range: ${minScore} to ${maxScore}`);
        console.log(`[getKillsFromIndex] Matches in range: ${rangeCount}`);

        if (indexTotal === 0) {
            console.warn(`[getKillsFromIndex] ⚠️ Index ${indexKey} is EMPTY!`);
        } else if (rangeCount === 0) {
            // Show actual range in index
            const [oldestEntry, newestEntry] = await Promise.all([
                redis.zrange(indexKey, 0, 0, 'WITHSCORES'),
                redis.zrevrange(indexKey, 0, 0, 'WITHSCORES')
            ]);
            console.warn(`[getKillsFromIndex] ⚠️ No kills in requested range`);
            console.warn(`[getKillsFromIndex] Index contains: ${oldestEntry[1]} to ${newestEntry[1]}`);
            console.warn(`[getKillsFromIndex] Requested: ${minScore} to ${maxScore}`);

            // Convert to human-readable dates for debugging
            const oldestDate = new Date(parseInt(oldestEntry[1]) * 1000).toISOString();
            const newestDate = new Date(parseInt(newestEntry[1]) * 1000).toISOString();
            console.warn(`[getKillsFromIndex] Index date range: ${oldestDate} to ${newestDate}`);
        }

        killIds = await redis.zrevrangebyscore(indexKey, maxScore, minScore);

    } else {
        // --- Default "last x" query (no time range) ---
        console.log(`[getKillsFromIndex] Getting latest ${limit} from ${indexKey}`);
        killIds = await redis.zrevrange(indexKey, 0, limit - 1);
    }

    const totalCount = killIds.length;

    if (totalCount === 0) {
        return {
            status: 'success',
            message: 'No kills found for criteria',
            query: queryParams,
            data: [],
            count: 0
        };
    }

    // Fetch limited data
    const killIdsToFetch = killIds.slice(0, limit);

    console.log(`[getKillsFromIndex] Found: ${totalCount}. Fetching details for: ${killIdsToFetch.length}`);

    const killmailStrings = await redis.hmget('intel:kill:data', ...killIdsToFetch);
    const killmails = killmailStrings.map(str => str ? JSON.parse(str) : null).filter(km => km);

    return {
        status: 'success',
        query: queryParams,
        data: killmails,
        count: totalCount
    };
}

// =====================================================
// QUERY DEFINITIONS
