        required: [],
        handler: async () => {
            const ping = await redis.ping();
            const dbSize = await redis.dbsize();
            const info = await redis.info('stats');

            return {
                status: 'healthy',
                redis_ping: ping,
                total_keys: dbSize,
                connection_status: redis.status,
                cache_stats: global.cacheStats || { hits: 0, misses: 0 }
            };
        }
    },

