        required: ['allianceName', 'allianceId'],
        requiresOneOf: true,
        handler: async (params) => {
            const entityId = params.allianceId || await resolveNameToId(params.allianceName);
            const stats = await redis.hgetall(`intel:stats:alliance:${entityId}`);

            if (!stats || Object.keys(stats).length === 0) {
                return { kill_count_total: 0, loss_count_total: 0, value_destroyed: 0, value_lost: 0 };
            }

            return {
                kill_count_total: parseInt(stats.kill_count_total, 10) || 0,
                loss_count_total: parseInt(stats.loss_count_total, 10) || 0,
                value_destroyed: parseFloat(stats.value_destroyed) || 0,
                value_lost: parseFloat(stats.value_lost) || 0,
                last_activity: stats.last_activity || null
            };
        }
    },

    character_stats: {
        required: ['characterName'],
        handler: async (params) => {
            const entityId = await resolveNameToId(params.characterName);
            const stats = await redis.hgetall(`intel:stats:character:${entityId}`);

            if (!stats || Object.keys(stats).length === 0) {
                return { kill_count_total: 0, loss_count_total: 0, value_destroyed: 0, value_lost: 0 };
