            const stats = await redis.hgetall(`intel:stats:corporation:${entityId}`);

            if (!stats || Object.keys(stats).length === 0) {
                return { kill_count_total: 0, loss_count_total: 0, value_destroyed: 0, value_lost: 0 };
            }

            return {
