            if (params.regionId) {
                regionId = params.regionId;
            } else {
                const nameLower = params.regionName.toLowerCase();
                regionId = await redis.hget('eve:region_name_to_id', nameLower);
                if (!regionId) throw new Error('Region not found.');
            }

            return await getKillsFromIndex(`intel:kills:region:${regionId}`, limit, inputData);
