    constellation_kills: {
        required: ['constellationName', 'constellationId'],
        requiresOneOf: true,
        handler: async (params) => {
            let constellationId;

            if (params.constellationId) {
                constellationId = params.constellationId;
            } else {
                const nameLower = params.constellationName.toLowerCase();
                constellationId = await redis.hget('eve:constellation_name_to_id', nameLower);
                if (!constellationId) throw new Error('Constellation not found.');
            }

            return await getKillsFromIndex(`intel:kills:constellation:${constellationId}`, limit, inputData);
        }
    },

    fleet_size_kills: {
        required: ['fleetSize'],
        handler: async (params) => {
            const validSizes = ['solo', 'small', 'medium', 'large'];
            const fleetSize = params.fleetSize.toLowerCase();

            if (!validSizes.includes(fleetSize)) {
                throw new Error(`Invalid fleet size. Must be one of: ${validSizes.join(', ')}`);
            }

            return await getKillsFromIndex(`intel:kills:fleet:${fleetSize}`, limit, inputData);
        }
    },

    kills_by_hour: {
        required: ['hour'],
        handler: async (params) => {
            const hour = parseInt(params.hour, 10);

            if (isNaN(hour) || hour < 0 || hour > 23) {
                throw new Error('Hour must be between 0-23 (UTC)');
            }

            return await getKillsFromIndex(`intel:kills:hour:${hour}`, limit, inputData);
        }
    },

    kills_by_day: {
        required: ['day'],
        handler: async (params) => {
            const dayNames = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];
            let dayNum;

            if (isNaN(params.day)) {
                const dayName = params.day.toLowerCase();
                dayNum = dayNames.indexOf(dayName);
                if (dayNum === -1) {
                    throw new Error(`Invalid day. Must be one of: ${dayNames.join(', ')}`);
                }
            } else {
                dayNum = parseInt(params.day, 10);
                if (dayNum < 0 || dayNum > 6) {
                    throw new Error('Day must be 0-6 (0=Sunday)');
                }
            }

            return await getKillsFromIndex(`intel:kills:day:${dayNum}`, limit, inputData);
        }
    },

    // =====================================================
    // SDE QUERIES (Alphabetical)
    // =====================================================
    get_agent_type: {
        required: ['agentTypeId'],
        handler: async (params) => {
            const dataJson = await redis.hget('eve:agent_types', params.agentTypeId);
            if (!dataJson) throw new Error(`Agent type ${params.agentTypeId} not found`);
            return JSON.parse(dataJson);
        }
    },

