        required: ['categoryId'],
        handler: async (params) => {
            const dataJson = await redis.hget('eve:attribute_categories', params.categoryId);
            if (!dataJson) throw new Error(`Attribute category ${params.categoryId} not found`);
            return JSON.parse(dataJson);
        }
    },

    get_blueprint_materials: {
        required: ['itemName'],
        handler: async (params) => {
            const typeId = await resolveNameToId(params.itemName);
            const bpJsonString = await redis.hget('eve:blueprint_materials', typeId);
            if (!bpJsonString) throw new Error('No blueprint data found');

            const bpData = JSON.parse(bpJsonString);
            const materialIds = Object.keys(bpData.materials);
            const materialNames = await redis.hmget('eve:id_to_name', ...materialIds);

            const detailedMaterials = Object.entries(bpData.materials).map(([matId, quantity], index) => ({
                materialID: parseInt(matId),
                materialName: materialNames[index] || `Unknown (${matId})`,
                quantity: quantity
            }));

            return {
                blueprintID: bpData.blueprintID,
                materials: detailedMaterials
            };
        }
    },

    get_blueprint_details: {
        required: ['itemName'],
        handler: async (params) => {
            const typeId = await resolveNameToId(params.itemName);
            const bpJson = await redis.hget('eve:blueprint_details', typeId);
            if (!bpJson) throw new Error('Blueprint not found');
            return JSON.parse(bpJson);
        }
    },

    bulk_price_lookup: {
        required: ['itemNames'],
        handler: async (params) => {
            if (!Array.isArray(params.itemNames)) {
                throw new Error('itemNames must be an array');
            }

            const results = [];
            for (const itemName of params.itemNames) {
                try {
                    const itemNameLower = itemName.toLowerCase();
                    const typeId = await redis.hget('eve:name_to_id', itemNameLower);

                    if (!typeId) {
                        results.push({ itemName, error: 'Item not found' });
                        continue;
                    }

                    const priceJsonString = await redis.hget('eve:market:prices', typeId);
                    if (!priceJsonString) {
                        results.push({ itemName, error: 'No price data' });
                        continue;
                    }

                    const priceData = JSON.parse(priceJsonString);
                    results.push({ itemName, typeId, ...priceData });
                } catch (error) {
                    results.push({ itemName, error: error.message });
                }
            }

            return results;
        }
    },

    get_character_attribute: {
