    get_item_market_group: {
        required: ['itemName'],
        handler: async (params) => {
            const typeId = await resolveNameToId(params.itemName);
            const marketGroupId = await redis.hget('eve:item_market_group', typeId);
            if (!marketGroupId) throw new Error('Item not on market');

            const marketGroupInfoJson = await redis.hget('eve:market_group_info', marketGroupId);
            const marketGroupName = marketGroupInfoJson ? JSON.parse(marketGroupInfoJson).name : 'Unknown';

            return { 
