        required: ['bonuses'],
        handler: async (params) => {
            if (!Array.isArray(params.bonuses)) {
                throw new Error('bonuses must be an array of numbers');
            }

            const sorted = [...params.bonuses].sort((a, b) => b - a);
            const results = sorted.map((bonus, i) => {
                const penalty = Math.exp(-Math.pow(i, 2) / 7.1289);
                return {
                    position: i + 1,
                    baseBonus: bonus,
                    penalty: penalty,
                    effectiveBonus: bonus * penalty
                };
            });

            return {
                totalBonus: results.reduce((sum, r) => sum + r.effectiveBonus, 0),
                details: results
            };
        }
    },

