// =====================================================
// MAIN EXECUTION
// =====================================================
const startTime = Date.now();

try {
    if (!queryType || !QUERIES[queryType]) {
        throw new Error(`Unknown query type: ${queryType}`);
    }

    const queryDef = QUERIES[queryType];

    // Validate parameters
    if (queryDef.requiresOneOf) {
        const hasAtLeastOne = queryDef.required.some(param => inputData[param]);
        if (!hasAtLeastOne) {
            throw new Error(`At least one required: ${queryDef.required.join(', ')}`);
        }
    } else if (queryDef.required.length > 0) {
        const missing = queryDef.required.filter(param => !inputData[param]);
        if (missing.length > 0) {
            throw new Error(`Missing required: ${missing.join(', ')}`);
        }
    }

    console.log(`[${queryType}] Executing...`);
    const data = await queryDef.handler(inputData);

    if (shouldCache && cacheKey) {
        global.queryCache.set(cacheKey, data);
        if (global.queryCache.size > 1000) {
            const firstKey = global.queryCache.keys().next().value;
            global.queryCache.delete(firstKey); 
        }
    }

    const duration = Date.now() - startTime;
    console.log(`[${queryType}] Completed in ${duration}ms`);

    return [{
        json: {
            status: 'success',
            query: inputData,
            data: data,
            performance: {
                query_type: queryType,
                duration_ms: duration,
                timestamp: new Date().toISOString()
            }
        }
    }];

} catch (error) {
    const duration = Date.now() - startTime;
    console.error(`[${queryType}] Error after ${duration}ms:`, error.message);

    return [{
        json: {
            status: 'error',
            message: error.message,
            query: inputData,
            performance: {
                query_type: queryType,
                duration_ms: duration,
                failed: true
            }
        }
    }];
}
